#include <cstdint>
#include <string>

std::string describe(std::uint32_t protection)
{
    std::string text;
    switch (protection & 0xFF)
    {
    case 0x01: text = "---"; break;
    case 0x02: text = "r--"; break;
    case 0x04: case 0x08: text = "rw-"; break;
    case 0x10: text = "--x"; break;
    case 0x20: text = "r-x"; break;
    case 0x40: case 0x80: text = "rwx"; break;
    default: return "???";
    }
    if (protection & 0x100) text += " guard";
    return text;
}

unitTests:
TEST("the basic values") { CHECK_EQ(describe(0x01), std::string("---")); CHECK_EQ(describe(0x02), std::string("r--")); CHECK_EQ(describe(0x04), std::string("rw-")); CHECK_EQ(describe(0x20), std::string("r-x")); CHECK_EQ(describe(0x40), std::string("rwx")); }
TEST("copy-on-write counts as writable") { CHECK_EQ(describe(0x08), std::string("rw-")); CHECK_EQ(describe(0x80), std::string("rwx")); }
TEST("execute only") { CHECK_EQ(describe(0x10), std::string("--x")); }
TEST("a guard page") { CHECK_EQ(describe(0x104), std::string("rw- guard")); }
TEST("other modifiers are ignored") { CHECK_EQ(describe(0x204), std::string("rw-")); }
TEST("unknown values") { CHECK_EQ(describe(0x00), std::string("???")); CHECK_EQ(describe(0x03), std::string("???")); }

